#include "fs_utils.h"
#include "user_utils.h"
#include <iostream>
#include <regex>
void login_cmd(std::vector<std::string>&p,EstadoGlobal&estado){if(estado.sesionActiva){std::cout<<"[ERROR] Ya existe una sesion activa. Debe ejecutar LOGOUT primero.\n";return;}std::string user,pass,id;for(size_t i=1;i<p.size();++i){std::string n,v;if(!dividir_parametro(p[i],n,v)){std::cout<<"[ERROR] LOGIN requiere parametros clave=valor\n";return;}n=minusculas(n);if(n=="user")user=v;else if(n=="pass")pass=v;else if(n=="id")id=v;else{std::cout<<"[ERROR] Parametro no reconocido: -"<<n<<"\n";return;}}if(user.empty()||pass.empty()||id.empty()){std::cout<<"[ERROR] LOGIN requiere -user, -pass y -id\n";return;}UbicacionParticion part;if(!abrir_particion_por_id(estado,id,part)){std::cout<<"[ERROR] La particion indicada no esta montada\n";return;}FILE*f=fopen(part.ruta.c_str(),"rb");if(!f){std::cout<<"[ERROR] No se pudo abrir el disco\n";return;}sbloque sb;if(!leer_super(f,part,sb)){fclose(f);return;}std::string users;if(!leer_users(f,sb,users)){fclose(f);std::cout<<"[ERROR] No existe users.txt\n";return;}fclose(f);std::vector<RegistroGrupo>gs;std::vector<RegistroUsuario>us;if(!parsear_users(users,gs,us)){std::cout<<"[ERROR] users.txt corrupto\n";return;}for(auto&u:us)if(u.activo&&u.user==user){if(u.pass!=pass){std::cout<<"[ERROR] Autenticacion fallida\n";return;}estado.sesionActiva=true;estado.sesion.user=u.user;estado.sesion.pass=u.pass;estado.sesion.grupo=u.grupo;estado.sesion.id_user=std::to_string(u.id);estado.sesion.id_grp=std::to_string(u.gid);estado.sesion.disco=id;std::cout<<"[EXITOSO] Sesion iniciada como "<<user<<" en "<<id<<"\n";return;}std::cout<<"[ERROR] El usuario no existe\n";}
void logout_cmd(std::vector<std::string>&,EstadoGlobal&estado){if(!estado.sesionActiva){std::cout<<"[ERROR] No existe una sesion activa\n";return;}std::cout<<"[EXITOSO] Sesion de "<<estado.sesion.user<<" cerrada\n";estado.sesion=usuario{};estado.sesionActiva=false;}
